CREATE TABLE src_wms.wms_receipt(id BIGINT AUTO_INCREMENT PRIMARY KEY,receipt_no VARCHAR(32) UNIQUE,asn_no VARCHAR(32),purchase_order_no VARCHAR(32),supplier_code VARCHAR(32),material_code VARCHAR(32),batch_no VARCHAR(64),received_qty DECIMAL(18,4),warehouse_code VARCHAR(32),status VARCHAR(20) DEFAULT 'PENDING_INSPECTION',inspection_no VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE src_wms.wms_putaway(id BIGINT AUTO_INCREMENT PRIMARY KEY,putaway_no VARCHAR(32) UNIQUE,receipt_no VARCHAR(32),material_code VARCHAR(32),batch_no VARCHAR(64),quantity DECIMAL(18,4),suggested_location VARCHAR(32),actual_location VARCHAR(32),status VARCHAR(20) DEFAULT 'CREATED',completed_at DATETIME(3));
